import{z as o,x as i,o as t,c as p,q as l,j as A,D as r,d as E,s,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"内核抢占","description":"","frontmatter":{"title":"内核抢占","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-preempt.md","filePath":"cs/kernel-preempt.md","lastUpdated":1791063341000}'),d={name:"cs/kernel-preempt.md"};function m(D,e,c,C,h,F){const B=i("Mermaid");return t(),p("div",null,[e[2]||(e[2]=l('<h1 id="内核抢占" tabindex="-1">内核抢占 <a class="header-anchor" href="#内核抢占" aria-label="Permalink to &quot;内核抢占&quot;">​</a></h1><div class="epigraph"><p>若内核在处理系统调用时不可抢占，高优先级线程必须等当前调用主动让出；打开抢占后，调度点遍布内核，锁与 per-CPU 的纪律必须更严。</p><footer>—— 据 Love, Linux Kernel Development；Silberschatz et al. 整理</footer></div><p><a href="/cs/nmi">上一课</a>说明连关中断都不能挡住一类入口。普通路径上，问题换成另一问：内核正在跑某线程的系统调用时，时钟中断来了，<strong>能不能立刻切到另一条更高优先级的内核/用户线程</strong>。传统 Unix 内核在返回用户前才调度（非抢占内核）；抢占内核在不持有自旋锁、抢占计数为零时允许切换。缺口是这道开关，不是 NMI 栈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非抢占：内核路径一直跑到睡眠或返回用户，实时任务的延迟等于「当前系统调用剩余」。抢占：中断返回内核时若 need_resched 且允许抢占，则<a href="/cs/context-switch">上下文切换</a>。缺口是：哪些区间禁止抢占——持自旋锁、硬/软中断上下文、显式 <code>preempt_disable</code>、以及 NMI。没有计数，抢占会在临界区中间把 per-CPU 假设拆掉。</p><p><span class="marginnote">抢占计数：关抢占、关软中断、在 IRQ 中，都会把计数抬高。为零才是「可在内核中被调度走」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配置打开内核抢占。时钟或唤醒把 <code>TIF_NEED_RESCHED</code> 一类位置上。中断返回、或显式 <code>preempt_enable</code> 降到零时，检查并调用调度器。睡眠本来就会切换，与抢占无关。驱动在遍历无锁 per-CPU 链表时必须关抢占，否则会被迁到另一 CPU。</p>',8)),(t(),A(n,null,{default:r(()=>[s(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E5%86%85%E6%A0%B8%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20CHK%5B%22%E6%8A%A2%E5%8D%A0%E8%AE%A1%E6%95%B0%E4%B8%BA%E9%9B%B6%3F%22%5D%0A%20%20CHK%20--%3E%20SW%5B%22%E5%8F%AF%E5%88%87%E6%8D%A2%22%5D%0A%20%20CHK%20--%3E%20HOLD%5B%22%E6%8C%81%E9%94%81%E6%88%96%20IRQ%3A%20%E4%B8%8D%E5%8F%AF%E6%8A%A2%E5%8D%A0%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[E("本课不把 "),a("code",null,"PREEMPT_RT"),E(" 的全面睡眠锁替换写完，只钉「内核是否可在中途被抢」。")],-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[E("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,[E("抢占把"),a("a",{href:"/cs/scheduling-metrics"},"调度指标"),E("里的响应从「系统调用边界」推进到「内核内部可抢占点」。代价是：凡假设「不会在这里换线程、换 CPU」的代码都必须显式关抢占。与"),a("a",{href:"/cs/interrupt-bottom-half"},"中断下半部"),E("叠加：软中断里仍不可睡，但可抢占内核在软中断外更早切换。实时对照课依赖这套点，否则 RM/EDF 只在用户态有效。")],-1)),e[6]||(e[6]=a("p",null,"这张图回答的问题是：同一个「实时任务被唤醒」事件，在两种内核下各要等多久才能上 CPU——差别就在切换点被推到哪。",-1)),(t(),A(n,null,{default:r(()=>[s(B,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20WK%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E4%BB%BB%E5%8A%A1%E8%A2%AB%E5%94%A4%E9%86%92%22%5D%20--%3E%20IRQ%5B%22%E6%97%B6%E9%92%9F%E4%B8%AD%E6%96%AD%E6%89%93%E6%96%AD%E4%BD%8E%E4%BC%98%E5%85%88%E7%BA%A7%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%0A%20%20IRQ%20--%3E%20K%7B%22%E5%86%85%E6%A0%B8%E5%8F%AF%E6%8A%A2%E5%8D%A0%EF%BC%9F%22%7D%0A%20%20K%20--%3E%7C%22%E5%90%A6%EF%BC%9A%E9%9D%9E%E6%8A%A2%E5%8D%A0%E5%86%85%E6%A0%B8%22%7C%20RETU%5B%22%E5%BF%85%E9%A1%BB%E7%AD%89%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E8%B7%91%E5%88%B0%E8%BF%94%E5%9B%9E%E7%94%A8%E6%88%B7%E6%80%81%22%5D%0A%20%20RETU%20--%3E%20LATE%5B%22%E5%BB%B6%E8%BF%9F%20%3D%20%E5%89%A9%E4%BD%99%E5%86%85%E6%A0%B8%E8%B7%AF%E5%BE%84%EF%BC%8C%E5%8F%AF%E8%BE%BE%E6%AF%AB%E7%A7%92%E7%BA%A7%22%5D%0A%20%20K%20--%3E%7C%22%E6%98%AF%EF%BC%9A%E6%8A%A2%E5%8D%A0%E5%86%85%E6%A0%B8%22%7C%20NOW%5B%22%E4%B8%AD%E6%96%AD%E8%BF%94%E5%9B%9E%E7%82%B9%E5%8D%B3%E6%A3%80%E6%9F%A5%20need_resched%22%5D%0A%20%20NOW%20--%3E%20FAST%5B%22%E7%AB%8B%E5%8D%B3%E5%88%87%E6%8D%A2%EF%BC%8C%E5%BB%B6%E8%BF%9F%E5%88%B0%E5%BE%AE%E7%A7%92%E9%87%8F%E7%BA%A7%22%5D%0A"})]),fallback:r(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=l('<p><span class="marginnote">数字实例：非抢占内核上，一次卡在文件系统或驱动的系统调用可能跑几毫秒，这就是实时任务的最坏等待；PREEMPT_RT 一类抢占配置把切换点搬进内核，典型最坏延迟压到几十微秒量级——差的是约两个数量级，不是性能微调。</span></p><p><span class="marginnote">直觉类比：抢占计数像客房门口的「请勿打扫」牌——持自旋锁、处于中断中、显式 <code>preempt_disable</code> 都是挂牌动作；计数非零时调度器（保洁）不许进来换人，牌子全摘（计数归零）才随时可换。</span></p><p><span class="marginnote">常见误区：初学者容易把「任务睡眠」当成「被抢占」。睡眠是任务自己调用了会阻塞的操作、主动让出 CPU；抢占是任务毫无准备地被时钟中断触发的调度点切走。两者切的位置、保存的状态路径都不同，后者才是本课要设防的场景。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不比较各发行版默认抢占模型，不把锁依赖检测器的全部规则写成正文。用户抢占（时间片用完回到用户再切）一直存在；本课对象是<strong>内核执行途中</strong>被切。</p><p>后课默认：可抢占内核里，CPU 本地的无锁数据必须配合关抢占或关中断。如何把数据结构做成每 CPU 一份以避开锁，下一课讲 per-CPU 数据。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内核抢占：在允许点从内核路径上被调度走。</li><li>自旋锁、IRQ、显式关抢占禁止切换。</li><li>per-CPU 无锁结构依赖这套计数，下一课展开。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const P=o(d,[["render",m]]);export{u as __pageData,P as default};
